settings.custom_css:
selector .ao-master-wrap {
  position: relative;
  overflow: hidden;
}
selector .ao-master-credential {
  display: flex;
  align-items: flex-start;
  gap: 20px;
  margin-bottom: 28px;
  padding: 24px 28px;
  background: linear-gradient(145deg, rgba(212,168,83,0.06), rgba(212,168,83,0.02));
  border: 1px solid rgba(212,168,83,0.12);
  border-radius: 16px;
  transition: border-color 0.3s ease;
}
selector .ao-master-credential:hover {
  border-color: rgba(212,168,83,0.3);
}
selector .ao-master-cred-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: linear-gradient(135deg, rgba(212,168,83,0.15), rgba(212,168,83,0.05));
  border: 1px solid rgba(212,168,83,0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 18px;
}
selector .ao-master-cred-title {
  font-family: 'Inter', sans-serif;
  font-size: 15px;
  font-weight: 700;
  color: #0d1117;
  line-height: 1.3;
  margin-bottom: 2px;
}
selector .ao-master-cred-sub {
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  color: rgba(13,17,23,0.45);
  line-height: 1.5;
}
selector .ao-master-quote-box {
  position: relative;
  margin-top: 40px;
  padding: 36px 32px;
  background: #0d1117;
  border-radius: 20px;
  overflow: hidden;
}
selector .ao-master-quote-box::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, #d4a853, transparent);
}
selector .ao-master-quote-text {
  font-family: 'Playfair Display', serif;
  font-style: italic;
  font-size: 17px;
  line-height: 1.65;
  color: rgba(255,255,255,0.8);
  margin: 0 0 24px 0;
}
selector .ao-master-quote-cite {
  font-family: 'Inter', sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: #d4a853;
}
selector .ao-master-img-wrap {
  position: relative;
  border-radius: 24px;
  overflow: hidden;
  box-shadow: 0 40px 80px rgba(13,17,23,0.12);
}
selector .ao-master-img-wrap img {
  width: 100%;
  display: block;
}
selector .ao-master-img-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 40px 32px;
  background: linear-gradient(to top, rgba(13,17,23,0.85), transparent);
}
selector .ao-master-img-badge {
  display: inline-block;
  font-family: 'Inter', sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: #d4a853;
  padding: 6px 14px;
  border: 1px solid rgba(212,168,83,0.3);
  border-radius: 99px;
  background: rgba(13,17,23,0.5);
  backdrop-filter: blur(10px);
}
selector .ao-master-cta {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 18px 44px;
  background: #d4a853;
  color: #050810;
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 2px;
  text-transform: uppercase;
  border-radius: 4px;
  text-decoration: none;
  box-shadow: 0 12px 30px rgba(212,168,83,0.2);
  transition: all 0.3s ease;
}
selector .ao-master-cta:hover {
  background: #c49a48;
  box-shadow: 0 16px 40px rgba(212,168,83,0.3);
}
@media (max-width: 767px) {
  selector .ao-master-credential { padding: 18px 20px; }
  selector .ao-master-cred-icon { width: 36px; height: 36px; font-size: 14px; }
  selector .ao-master-quote-box { padding: 28px 24px; }
  selector .ao-master-img-overlay { padding: 28px 20px; }
}
